@app.route('/api/admin/save-config', methods=['POST'])
def save_admin_config():
    """Save API configuration to .env file"""
    try:
        data = request.get_json()

        # Read existing .env file
        env_path = os.path.join(os.path.dirname(__file__), '.env')
        env_lines = []

        if os.path.exists(env_path):
            with open(env_path, 'r') as f:
                env_lines = f.readlines()

        # Configuration keys to update
        config_keys = {
            'NAC_API_KEY': data.get('nac_api_key', ''),
            'NEXUS_API_KEY': data.get('nexus_api_key', ''),
            'NEXUS_URL': data.get('nexus_url', ''),
            'NEXUS_USERNAME': data.get('nexus_username', '')
        }

        # Update or add configuration
        updated_keys = set()
        for i, line in enumerate(env_lines):
            for key, value in config_keys.items():
                if line.startswith(f'{key}='):
                    env_lines[i] = f'{key}={value}\n'
                    updated_keys.add(key)
                    break

        # Add new keys that weren't found
        for key, value in config_keys.items():
            if key not in updated_keys:
                env_lines.append(f'{key}={value}\n')

        # Write back to .env file
        with open(env_path, 'w') as f:
            f.writelines(env_lines)

        return jsonify({
            'status': 'success',
            'message': 'Configuration saved successfully'
        })

    except Exception as e:
        return jsonify({
            'status': 'error',
            'message': f'Failed to save configuration: {str(e)}'
        }), 500


@app.route('/api/admin/load-config', methods=['GET'])
def load_admin_config():
    """Load current API configuration"""
    try:
        return jsonify({
            'status': 'success',
            'data': {
                'nac_api_key': os.getenv('NAC_API_KEY', ''),
                'nexus_api_key': os.getenv('NEXUS_API_KEY', ''),
                'nexus_url': os.getenv('NEXUS_URL', ''),
                'nexus_username': os.getenv('NEXUS_USERNAME', '')
            }
        })
    except Exception as e:
        return jsonify({
            'status': 'error',
            'message': f'Failed to load configuration: {str(e)}'
        }), 500


@app.route('/api/admin/clear-config', methods=['POST'])
def clear_admin_config():
    """Clear API configuration from .env file"""
    try:
        # Read existing .env file
        env_path = os.path.join(os.path.dirname(__file__), '.env')
        env_lines = []

        if os.path.exists(env_path):
            with open(env_path, 'r') as f:
                env_lines = f.readlines()

        # Remove configuration keys
        config_keys = ['NAC_API_KEY', 'NEXUS_API_KEY', 'NEXUS_URL', 'NEXUS_USERNAME']
        filtered_lines = [line for line in env_lines
                         if not any(line.startswith(f'{key}=') for key in config_keys)]

        # Write back to .env file
        with open(env_path, 'w') as f:
            f.writelines(filtered_lines)

        return jsonify({
            'status': 'success',
            'message': 'Configuration cleared successfully'
        })

    except Exception as e:
        return jsonify({
            'status': 'error',
            'message': f'Failed to clear configuration: {str(e)}'
        }), 500

