}


/**
 * Handle admin form submission
 */
async function handleAdminFormSubmit(event) {
    event.preventDefault();

    const responseDiv = document.getElementById('apiKeysResponse');
    const formData = {
        nac_api_key: document.getElementById('nacApiKey').value,
        nexus_api_key: document.getElementById('nexusApiKey').value,
        nexus_url: document.getElementById('nexusUrl').value,
        nexus_username: document.getElementById('nexusUsername').value
    };

    try {
        const response = await fetch('/api/admin/save-config', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(formData)
        });

        const data = await response.json();

        if (data.status === 'success') {
            responseDiv.textContent = `✓ ${data.message}`;
            responseDiv.className = 'alert alert-success';
            responseDiv.style.display = 'block';

            // Update last config update timestamp
            const timestamp = new Date().toLocaleString();
            const lastUpdateEl = document.getElementById('lastConfigUpdate');
            if (lastUpdateEl) {
                lastUpdateEl.textContent = timestamp;
            }
        } else {
            throw new Error(data.message || 'Failed to save configuration');
        }
    } catch (error) {
        console.error('Admin config save error:', error);
        responseDiv.textContent = `✗ Error: ${error.message}`;
        responseDiv.className = 'alert alert-danger';
        responseDiv.style.display = 'block';
    }

    // Smooth scroll to response
    responseDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}


