 * Load admin configuration
 */
async function loadAdminConfig() {
    const responseDiv = document.getElementById('apiKeysResponse');

    try {
        const response = await fetch('/api/admin/load-config');
        const result = await response.json();

        if (result.status === 'success') {
            const data = result.data;

            // Populate form fields
            document.getElementById('nacApiKey').value = data.nac_api_key || '';
            document.getElementById('nexusApiKey').value = data.nexus_api_key || '';
            document.getElementById('nexusUrl').value = data.nexus_url || '';
            document.getElementById('nexusUsername').value = data.nexus_username || '';

            responseDiv.textContent = '✓ Configuration loaded successfully';
            responseDiv.className = 'alert alert-info';
            responseDiv.style.display = 'block';
        } else {
            throw new Error(result.message || 'Failed to load configuration');
        }
    } catch (error) {
        console.error('Admin config load error:', error);
        responseDiv.textContent = `✗ Error: ${error.message}`;
        responseDiv.className = 'alert alert-danger';
        responseDiv.style.display = 'block';
    }

    // Smooth scroll to response
    responseDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
